export function verifyWhatsAppToken(token: string): boolean {
  return token === process.env.WHATSAPP_VERIFY_TOKEN;
}

export const whatsappWebhook = async (
  req: Request,
  res: Response,
  next: NextFunction,
) => {
  try {
    const { body } = req;

    // Auth: two accepted paths.
    //
    // 1. Meta signature (X-Hub-Signature-256) — normal inbound from Meta.
    // 2. Internal forward header — this deployment is receiving a payload
    //    forwarded by ANOTHER deployment of ours (see whatsapp-forward.service).
    //    The forwarding deployment can't re-sign for Meta's app secret, so
    //    we accept a shared secret in X-Internal-Forward instead.
    const allowInsecureWebhooks =
      process.env.ALLOW_INSECURE_WEBHOOKS === "true";
    const mustVerify =
      process.env.NODE_ENV === "production" || !allowInsecureWebhooks;
    if (mustVerify) {
      const forwardSecret = process.env.INTERNAL_FORWARD_SECRET;
      const forwardHeader = req.header("x-internal-forward");
      const isInternalForward = Boolean(
        forwardSecret && forwardHeader && forwardHeader === forwardSecret,
      );

      if (!isInternalForward) {
        if (!process.env.WHATSAPP_APP_SECRET) {
          return next(new Error("WHATSAPP_APP_SECRET is not configured"));

