INSERT INTO ledger_lines (id, journal_entry_id, ledger_account_id, direction, amount, currency) SELECT gen_random_uuid(), j.id, a.id, 'DEBIT', 100, 'NGN' FROM journal_entries j, ledger_accounts a WHERE a.code='TEST_WALLET' LIMIT 1;
SAVEPOINT s1;
UPDATE ledger_lines SET amount = 999;
ROLLBACK TO s1;
DELETE FROM journal_entries;
ROLLBACK TO s1;
INSERT INTO ledger_lines (id, journal_entry_id, ledger_account_id, direction, amount, currency) SELECT gen_random_uuid(), j.id, a.id, 'DEBIT', -5, 'NGN' FROM journal_entries j, ledger_accounts a LIMIT 1;
ROLLBACK TO s1;
INSERT INTO ledger_accounts (id, type, currency, updated_at) VALUES (gen_random_uuid(), 'ASSET', 'NGN', now());
ROLLBACK;
